389	/// Detect the current shell.
390	fn detect_shell() -> String {
391	    if cfg!(target_os = "windows") {
392	        std::env::var("COMSPEC").unwrap_or_else(|_| "cmd.exe".to_string())
393	    } else {
394	        std::env::var("SHELL").unwrap_or_else(|_| "/bin/sh".to_string())
395	    }
