//! Cache storage implementation.

use anyhow::{Context, Result};
use sha2::{Digest, Sha256};
use std::fs;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicU64, Ordering};

use super::entry::CacheEntry;

static WRITE_COUNTER: AtomicU64 = AtomicU64::new(0);

/// Write to a temporary file then atomically rename into place.
fn atomic_write(path: &Path, content: &[u8]) -> Result<()> {
    let unique = WRITE_COUNTER.fetch_add(1, Ordering::Relaxed);
    let tmp_ext = format!("tmp.{}.{}", std::process::id(), unique);
    let tmp_path = path.with_extension(tmp_ext);
    fs::write(&tmp_path, content)
        .with_context(|| format!("Failed to write temporary file {:?}", tmp_path))?;
    fs::rename(&tmp_path, path)
        .with_context(|| format!("Failed to rename {:?} to {:?}", tmp_path, path))?;
    Ok(())
}

fn remove_if_exists(path: &Path) -> Result<bool> {
    match fs::remove_file(path) {
        Ok(()) => Ok(true),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(false),
        Err(e) => Err(e).with_context(|| format!("Failed to remove {:?}", path)),
    }
}

