        let path1 = store.content_path("http:test", "template1");
        let path2 = store.content_path("http:test", "template2");

        assert_ne!(path1, path2);
    }

    #[test]
    fn concurrent_stores_to_different_keys() {
        use std::sync::Arc;

        let temp = TempDir::new().unwrap();
        let store = Arc::new(CacheStore::new(temp.path()));

        let handles: Vec<_> = (0..10)
            .map(|i| {
                let store = Arc::clone(&store);
                std::thread::spawn(move || {
                    let source = format!("http:source-{}", i);
                    let content = format!("content-for-{}", i);
                    store.store(&source, "template", &content, 3600).unwrap();
                })
            })
            .collect();

        for handle in handles {
            handle.join().unwrap();
        }

        for i in 0..10 {
            let source = format!("http:source-{}", i);
            let entry = store.load(&source, "template").unwrap().unwrap();
            let content = store.read_content(&entry).unwrap();
            assert_eq!(content, format!("content-for-{}", i));
        }
    }

    #[test]
    fn concurrent_stores_to_same_key() {
        use std::sync::{Arc, Barrier};

        let temp = TempDir::new().unwrap();
        let store = Arc::new(CacheStore::new(temp.path()));
        let barrier = Arc::new(Barrier::new(10));

        let handles: Vec<_> = (0..10)
            .map(|i| {
                let store = Arc::clone(&store);
                let barrier = Arc::clone(&barrier);
                std::thread::spawn(move || {
                    barrier.wait();
                    let content = format!("content-{}", i);
                    store
                        .store("http:race", "template", &content, 3600)
                        .unwrap();
                })
            })
            .collect();

        for handle in handles {
            handle.join().unwrap();
        }

        let entry = store.load("http:race", "template").unwrap().unwrap();
        let content = store.read_content(&entry).unwrap();
        assert!(
            content.starts_with("content-"),
            "content should be from one of the writers, got: {}",
            content
        );
        assert_eq!(entry.source_id, "http:race");
        assert_eq!(entry.template_name, "template");
    }

    #[test]
    fn concurrent_reads_during_writes() {
        use std::sync::{Arc, Barrier};

        let temp = TempDir::new().unwrap();
        let store = Arc::new(CacheStore::new(temp.path()));

        store
            .store("http:test", "template", "initial", 3600)
            .unwrap();

        let barrier = Arc::new(Barrier::new(20));

        let handles: Vec<_> = (0..20)
            .map(|i| {
                let store = Arc::clone(&store);
                let barrier = Arc::clone(&barrier);
                std::thread::spawn(move || {
                    barrier.wait();
                    if i % 2 == 0 {
                        let content = format!("updated-{}", i);
                        store
                            .store("http:test", "template", &content, 3600)
                            .unwrap();
                    } else {
                        match store.load("http:test", "template") {
                            Ok(Some(entry)) => {
                                let content = store.read_content(&entry).unwrap();
                                assert!(
                                    content == "initial" || content.starts_with("updated-"),
                                    "unexpected content: {}",
                                    content
                                );
                            }
                            Ok(None) => panic!("entry should always exist"),
                            Err(e) => panic!("load should not fail: {}", e),
                        }
                    }
                })
            })
            .collect();

        for handle in handles {
            handle.join().unwrap();
        }
    }

    #[test]
    fn no_temp_files_left_after_store() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store
            .store("http:test", "template", "content", 3600)
            .unwrap();

        let files: Vec<_> = fs::read_dir(temp.path())
            .unwrap()
            .filter_map(|e| e.ok())
            .filter(|e| {
                e.path()
                    .to_string_lossy()
                    .contains(".tmp.")
            })
            .collect();

        assert!(files.is_empty(), "temp files should be cleaned up: {:?}", files);
    }
}

