11	static WRITE_COUNTER: AtomicU64 = AtomicU64::new(0);
12	
13	/// Write to a temporary file then atomically rename into place.
14	fn atomic_write(path: &Path, content: &[u8]) -> Result<()> {
15	    let unique = WRITE_COUNTER.fetch_add(1, Ordering::Relaxed);
16	    let tmp_ext = format!("tmp.{}.{}", std::process::id(), unique);
17	    let tmp_path = path.with_extension(tmp_ext);
18	    fs::write(&tmp_path, content)
19	        .with_context(|| format!("Failed to write temporary file {:?}", tmp_path))?;
20	    fs::rename(&tmp_path, path)
21	        .with_context(|| format!("Failed to rename {:?} to {:?}", tmp_path, path))?;
22	    Ok(())
23	}
24	
25	fn remove_if_exists(path: &Path) -> Result<bool> {
26	    match fs::remove_file(path) {
27	        Ok(()) => Ok(true),
28	        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(false),
29	        Err(e) => Err(e).with_context(|| format!("Failed to remove {:?}", path)),
30	    }
31	}
