33	/// Storage for cached templates.
34	pub struct CacheStore {
35	    /// Root directory for cache.
36	    root: PathBuf,
37	}
38	
39	impl CacheStore {
40	    /// Create a new cache store.
41	    pub fn new(root: impl Into<PathBuf>) -> Self {
42	        Self { root: root.into() }
43	    }
44	
45	    /// Get the cache root directory.
46	    pub fn root(&self) -> &Path {
47	        &self.root
48	    }
49	
50	    /// Ensure the cache directory exists.
51	    fn ensure_dir(&self) -> Result<()> {
52	        fs::create_dir_all(&self.root)
53	            .with_context(|| format!("Failed to create cache directory {:?}", self.root))
54	    }
55	
56	    /// Get the path for storing an entry's content.
57	    pub fn content_path(&self, source_id: &str, template_name: &str) -> PathBuf {
58	        let key = format!("{}:{}", source_id, template_name);
59	        let hash = Sha256::digest(key.as_bytes());
60	        let hash_str = hex::encode(&hash[..16]);
61	        self.root.join(hash_str)
62	    }
63	
64	    /// Get the metadata file path for an entry.
65	    fn metadata_path(&self, source_id: &str, template_name: &str) -> PathBuf {
66	        self.content_path(source_id, template_name)
67	            .with_extension("meta.json")
68	    }
69	
70	    /// Store content and return a cache entry.
71	    pub fn store(
72	        &self,
73	        source_id: &str,
74	        template_name: &str,
75	        content: &str,
76	        ttl_seconds: u64,
77	    ) -> Result<CacheEntry> {
78	        self.ensure_dir()?;
79	
80	        let content_path = self.content_path(source_id, template_name);
81	        atomic_write(&content_path, content.as_bytes())?;
82	
83	        let entry = CacheEntry::new(source_id, template_name, &content_path, ttl_seconds)
84	            .with_size(content.len() as u64);
85	
86	        self.save_metadata(&entry)?;
87	
88	        Ok(entry)
89	    }
90	
91	    /// Load a cached entry's metadata.
92	    pub fn load(&self, source_id: &str, template_name: &str) -> Result<Option<CacheEntry>> {
93	        let meta_path = self.metadata_path(source_id, template_name);
94	        let json = match fs::read_to_string(&meta_path) {
95	            Ok(json) => json,
96	            Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(None),
97	            Err(e) => {
98	                return Err(e)
99	                    .with_context(|| format!("Failed to read metadata {:?}", meta_path))
100	            }
101	        };
102	        let entry: CacheEntry = serde_json::from_str(&json)?;
103	        Ok(Some(entry))
104	    }
105	
106	    /// Read the cached content.
107	    pub fn read_content(&self, entry: &CacheEntry) -> Result<String> {
108	        fs::read_to_string(&entry.content_path).with_context(|| {
109	            format!(
110	                "Failed to read cached content from {:?}",
111	                entry.content_path
112	            )
113	        })
114	    }
115	
116	    /// Save entry metadata.
117	    fn save_metadata(&self, entry: &CacheEntry) -> Result<()> {
118	        let meta_path = self.metadata_path(&entry.source_id, &entry.template_name);
119	        let json = serde_json::to_string_pretty(entry)?;
120	        atomic_write(&meta_path, json.as_bytes())
121	    }
122	
123	    /// Update an entry's metadata (e.g., after revalidation).
124	    pub fn update(&self, entry: &CacheEntry) -> Result<()> {
125	        self.save_metadata(entry)
126	    }
127	
128	    /// Atomically write content for a cache entry.
129	    pub(crate) fn write_content_file(
130	        &self,
131	        source_id: &str,
132	        template_name: &str,
133	        content: &str,
134	    ) -> Result<()> {
135	        self.ensure_dir()?;
136	        let content_path = self.content_path(source_id, template_name);
137	        atomic_write(&content_path, content.as_bytes())
138	    }
139	
140	    /// Remove a cached entry.
141	    pub fn remove(&self, source_id: &str, template_name: &str) -> Result<bool> {
142	        let content_path = self.content_path(source_id, template_name);
143	        let meta_path = self.metadata_path(source_id, template_name);
144	        let content_removed = remove_if_exists(&content_path)?;
145	        let meta_removed = remove_if_exists(&meta_path)?;
146	        Ok(content_removed || meta_removed)
147	    }
148	
149	    /// List all cached entries.
150	    pub fn list(&self) -> Result<Vec<CacheEntry>> {
151	        self.ensure_dir()?;
152	
153	        let mut entries = Vec::new();
154	
155	        for entry in fs::read_dir(&self.root)? {
156	            let entry = entry?;
157	            let path = entry.path();
158	
159	            if path.extension().is_some_and(|e| e == "json") {
160	                if let Ok(json) = fs::read_to_string(&path) {
161	                    if let Ok(cache_entry) = serde_json::from_str::<CacheEntry>(&json) {
162	                        entries.push(cache_entry);
163	                    }
164	                }
165	            }
166	        }
167	
168	        entries.sort_by_key(|e| std::cmp::Reverse(e.metadata.cached_at));
169	        Ok(entries)
170	    }
171	
172	    /// Clear all cached entries.
173	    pub fn clear(&self) -> Result<usize> {
174	        let entries = self.list()?;
175	        let count = entries.len();
176	
177	        for entry in entries {
178	            let _ = self.remove(&entry.source_id, &entry.template_name);
179	        }
180	
181	        Ok(count)
182	    }
183	
184	    /// Get total cache size in bytes.
185	    pub fn total_size(&self) -> Result<u64> {
186	        let entries = self.list()?;
187	        Ok(entries.iter().map(|e| e.metadata.size_bytes).sum())
188	    }
189	}
