149	    #[test]
150	    fn revalidator_creation() {
151	        let temp = TempDir::new().unwrap();
152	        let store = CacheStore::new(temp.path());
153	
154	        let git_dir = temp.path().join("git");
155	        let _revalidator = CacheRevalidator::new(&store, git_dir);
156	    }
157	
158	    #[test]
159	    fn revalidation_result_variants() {
160	        let unchanged = RevalidationResult::Unchanged;
161	        let updated = RevalidationResult::Updated("new content".to_string());
162	        let failed = RevalidationResult::Failed("network error".to_string());
163	
164	        // Just check we can pattern match
165	        match unchanged {
166	            RevalidationResult::Unchanged => {}
167	            _ => panic!("expected Unchanged"),
168	        }
169	
170	        match updated {
171	            RevalidationResult::Updated(content) => assert_eq!(content, "new content"),
172	            _ => panic!("expected Updated"),
173	        }
174	
175	        match failed {
176	            RevalidationResult::Failed(msg) => assert_eq!(msg, "network error"),
177	            _ => panic!("expected Failed"),
178	        }
179	    }
180	
181	    // --- Mock HTTP revalidation tests ---
182	
183	    #[test]
184	    fn etag_revalidation_unchanged_on_304() {
185	        let server = MockServer::start();
186	
187	        let mock = server.mock(|when, then| {
188	            when.method(GET)
189	                .path("/template.yml")
190	                .header("If-None-Match", "\"etag-v1\"");
191	            then.status(304);
192	        });
193	
194	        let temp = TempDir::new().unwrap();
195	        let store = CacheStore::new(temp.path());
196	        let git_dir = temp.path().join("git");
197	        let revalidator = CacheRevalidator::new(&store, git_dir);
198	
199	        // Create an expired cache entry with an etag
200	        let mut entry = store
201	            .store("http:test", "template", "old content", 0)
202	            .unwrap();
203	        entry.metadata.etag = Some("\"etag-v1\"".to_string());
204	        store.update(&entry).unwrap();
205	
206	        let result = revalidator
207	            .revalidate_etag(&server.url("/template.yml"), &mut entry, 3600)
208	            .unwrap();
209	
210	        mock.assert();
211	        assert!(matches!(result, RevalidationResult::Unchanged));
212	        // TTL should be extended
213	        assert!(!entry.is_expired());
214	    }
215	
216	    #[test]
217	    fn etag_revalidation_updated_on_200() {
218	        let server = MockServer::start();
219	
220	        server.mock(|when, then| {
221	            when.method(GET).path("/template.yml");
222	            then.status(200)
223	                .header("ETag", "\"etag-v2\"")
224	                .body("new content");
225	        });
226	
227	        let temp = TempDir::new().unwrap();
228	        let store = CacheStore::new(temp.path());
229	        let git_dir = temp.path().join("git");
230	        let revalidator = CacheRevalidator::new(&store, git_dir);
231	
232	        // Create an expired cache entry with an old etag
233	        let mut entry = store
234	            .store("http:test", "template", "old content", 0)
235	            .unwrap();
236	        entry.metadata.etag = Some("\"etag-v1\"".to_string());
237	        store.update(&entry).unwrap();
238	
239	        let result = revalidator
240	            .revalidate_etag(&server.url("/template.yml"), &mut entry, 3600)
241	            .unwrap();
242	
243	        match result {
244	            RevalidationResult::Updated(content) => {
245	                assert_eq!(content, "new content");
246	            }
247	            other => panic!("Expected Updated, got {:?}", other),
248	        }
249	
250	        // ETag should be updated
251	        assert_eq!(entry.metadata.etag, Some("\"etag-v2\"".to_string()));
252	        // TTL should be extended
253	        assert!(!entry.is_expired());
254	    }
255	
256	    #[test]
257	    fn etag_revalidation_updates_cached_content_on_disk() {
258	        let server = MockServer::start();
259	
260	        server.mock(|when, then| {
261	            when.method(GET).path("/template.yml");
262	            then.status(200)
263	                .header("ETag", "\"etag-v2\"")
264	                .body("updated content on disk");
265	        });
266	
267	        let temp = TempDir::new().unwrap();
268	        let store = CacheStore::new(temp.path());
269	        let git_dir = temp.path().join("git");
270	        let revalidator = CacheRevalidator::new(&store, git_dir);
271	
